SELECT customers.segment, CASE WHEN customers.country IN ('TH', 'SG') THEN 'core' ELSE 'other' END country_group, COUNT(web_events.duration_sec) duration_sec_count, MIN(web_events.duration_sec) min_duration_sec FROM web_events INNER JOIN sessions ON web_events.session_id = sessions.id RIGHT JOIN customers ON sessions.customer_id = customers.id WHERE sessions.country IN ('UK', 'JP') GROUP BY customers.segment, CASE WHEN customers.country IN ('TH', 'SG') THEN 'core' ELSE 'other' END HAVING MIN(web_events.duration_sec) > 430;
